CREATE TABLE sources (id TEXT PRIMARY KEY, cursor TEXT NOT NULL DEFAULT '{}', next_poll_at INTEGER NOT NULL DEFAULT 0, active_job TEXT, last_success_at INTEGER, last_error TEXT);
CREATE TABLE jobs (id TEXT PRIMARY KEY, type TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', available_at INTEGER NOT NULL, dispatched_at INTEGER, lease_until INTEGER, lease_token TEXT, attempts INTEGER NOT NULL DEFAULT 0, error TEXT, created_at INTEGER NOT NULL);
CREATE INDEX jobs_due ON jobs(state, available_at, dispatched_at);
CREATE TABLE threats (key TEXT PRIMARY KEY, revision_id TEXT, material TEXT NOT NULL DEFAULT '', generation INTEGER NOT NULL DEFAULT 0);
CREATE TABLE evidence (threat_key TEXT NOT NULL, id TEXT NOT NULL, hash TEXT NOT NULL, source_version TEXT NOT NULL, current INTEGER NOT NULL DEFAULT 1, modified_at INTEGER NOT NULL, fetched_at INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY(threat_key,id,hash));
CREATE TABLE source_versions (id TEXT PRIMARY KEY, version_hash TEXT NOT NULL, modified_at INTEGER NOT NULL, fetched_at INTEGER NOT NULL);
CREATE UNIQUE INDEX evidence_current ON evidence(threat_key,id) WHERE current=1;
CREATE INDEX evidence_identity ON evidence(id,current);
CREATE TABLE revisions (id TEXT PRIMARY KEY, threat_key TEXT NOT NULL, snapshot TEXT NOT NULL, evidence_hash TEXT NOT NULL, kind TEXT NOT NULL, event_at INTEGER NOT NULL, priority INTEGER NOT NULL, urgent INTEGER NOT NULL, eligible INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX revisions_priority ON revisions(eligible,priority,event_at DESC);
CREATE TABLE summaries (revision_id TEXT PRIMARY KEY, evidence_hash TEXT NOT NULL, summary TEXT NOT NULL, validation TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE targets (id TEXT PRIMARY KEY, paused INTEGER NOT NULL DEFAULT 0, reason TEXT, active_delivery TEXT, last_attempt_at INTEGER, last_normal_at INTEGER, last_urgent_at INTEGER);
CREATE TABLE deliveries (id TEXT PRIMARY KEY, target_id TEXT NOT NULL, revision_id TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'ready', urgent INTEGER NOT NULL, available_at INTEGER NOT NULL, lease_token TEXT, lease_until INTEGER, reserved_day TEXT, post_id TEXT, post_url TEXT, prepared TEXT, error TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(target_id,revision_id));
CREATE INDEX deliveries_due ON deliveries(state, available_at);
CREATE INDEX deliveries_history ON deliveries(target_id,state,updated_at DESC);
CREATE TABLE attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, delivery_id TEXT NOT NULL, token TEXT NOT NULL, state TEXT NOT NULL, at INTEGER NOT NULL, error TEXT);
CREATE TABLE quotas (target_id TEXT NOT NULL, day TEXT NOT NULL, bucket TEXT NOT NULL, used INTEGER NOT NULL DEFAULT 0 CHECK(used>=0), PRIMARY KEY(target_id,day,bucket));
CREATE TABLE budgets (day TEXT PRIMARY KEY, calls INTEGER NOT NULL DEFAULT 0, neurons REAL NOT NULL DEFAULT 0, queue_ops INTEGER NOT NULL DEFAULT 0);
CREATE TABLE budget_reservations (id TEXT PRIMARY KEY, day TEXT NOT NULL, amount REAL NOT NULL, state TEXT NOT NULL DEFAULT 'reserved', charged INTEGER NOT NULL DEFAULT 0, lease_until INTEGER NOT NULL);
CREATE INDEX budget_active ON budget_reservations(state,lease_until);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE shortened_summaries (delivery_id TEXT PRIMARY KEY, evidence_hash TEXT NOT NULL, summary TEXT NOT NULL, validation TEXT NOT NULL);
